m add access-rule layer Network_trust_to_untrust position bottom name to-branch-vpn source.1 inside-net destination.1 All-IPv4 service.1 Any action Accept track.type None enabled false comments 'FWSHIFT: disabled by the converter, see the report.' ignore-warnings true
m add access-rule layer Network_trust_to_untrust position bottom name contractors-out source.1 wild-hosts destination.1 All-IPv4 service.1 Any action Accept track.type None enabled false comments 'FWSHIFT: disabled by the converter, see the report.' ignore-warnings true
m add access-rule layer Network_trust_to_untrust position bottom name 'FWShift cleanup' source.1 Any destination.1 Any service.1 Any action Drop track.type Log comments 'Added by FWShift: the source drops what no rule allows.' ignore-warnings true
m add access-rule layer Network position 2 name 'trust to untrust' source.1 trust destination.1 untrust service.1 Any action 'Apply Layer' inline-layer Network_trust_to_untrust ignore-warnings true

